import { readFileSync, writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

export function buildBundle(core, worker) {
  return '// GMT Procurement — Cloudflare Workers single-file distribution\n' +
    '// Generated by scripts/build-single-file.mjs; DEFAULT OFF; no embedded secrets.\n\n' +
    core.replace(/^export /gm, '') + '\n' +
    worker.replace(/^import [\s\S]*?from '\.\/core\.mjs';\r?\n/, '');
}
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const root = new URL('../', import.meta.url);
  writeFileSync(new URL('cloudflare-single-file.mjs', root), buildBundle(
    readFileSync(new URL('src/core.mjs', root), 'utf8'),
    readFileSync(new URL('src/worker.mjs', root), 'utf8')));
}

